const fs = require('fs');
const path = require('path');

const inputPath = path.join(__dirname, 'README.md');
const outputPath = path.join(__dirname, 'INDEX.md');

const content = fs.readFileSync(inputPath, 'utf8');
const headings = content.split(/\r?\n/).filter((line) => line.startsWith('#'));

fs.writeFileSync(outputPath, headings.join('\n') + '\n');

console.log('Wrote ' + headings.length + ' heading(s) to INDEX.md');

